<?php require_once __DIR__.'/functions.php'; require_once __DIR__.'/app_init.php'; require_login(); $pdo=dogvive_db(); $uid=dogvive_user_id();
if($_SERVER['REQUEST_METHOD']==='POST'){try{$name=trim((string)($_POST['nombre']??''));$phone=trim((string)($_POST['telefono']??''));$email=strtolower(trim((string)($_POST['correo']??'')));$city=trim((string)($_POST['ciudad']??''));$user=trim((string)($_POST['usuario']??''));if(mb_strlen($name)<3||!filter_var($email,FILTER_VALIDATE_EMAIL)||$phone===''||$city===''||!preg_match('/^[a-zA-Z0-9_.-]{3,60}$/',$user))throw new RuntimeException('Revisa nombre, correo, teléfono, ciudad y usuario.');$parts=preg_split('/\s+/', $name,2)?:[$name];$s=$pdo->prepare('SELECT id_usuario FROM usuario WHERE (Correo=? OR Usuario=?) AND id_usuario<>?');$s->execute([$email,$user,$uid]);if($s->fetch())throw new RuntimeException('Ese correo o usuario ya está registrado por otra cuenta.');$q=$pdo->prepare('UPDATE usuario SET Nombre=?,Apellido=?,Correo=?,Telefono=?,Direccion=?,Ciudad=?,Usuario=? WHERE id_usuario=?');$q->execute([$parts[0],$parts[1]??'',$email,$phone,$city,$city,$user,$uid]);$_SESSION['dogvibe_user']['nombre']=$name;$_SESSION['dogvibe_user']['correo']=$email;$_SESSION['dogvibe_user']['telefono']=$phone;$_SESSION['dogvibe_user']['ciudad']=$city;$_SESSION['dogvibe_user']['usuario']=$user;dogvive_flash('success','Tus datos fueron actualizados.');header('Location: '.base_url().'/perfil.php');exit;}catch(Throwable $e){dogvive_flash('error',$e instanceof RuntimeException?$e->getMessage():'No se pudo actualizar el perfil.');header('Location: '.base_url().'/editar-perfil.php');exit;}}
$q=$pdo->prepare('SELECT * FROM usuario WHERE id_usuario=?');$q->execute([$uid]);$u=$q->fetch();start_app('Editar perfil','perfil');page_wrap_start('Editar perfil','Actualiza los datos asociados a tu cuenta.');$err=dogvive_flash('error');if($err)echo '<div class="error-box">'.e($err).'</div>'; ?>
<div class="card form-box" style="max-width:800px"><form method="post"><label>Nombre completo<input name="nombre" value="<?= e(trim(($u['Nombre']??'').' '.($u['Apellido']??''))) ?>" required></label><div class="form-grid"><label>Correo electrónico<input type="email" name="correo" value="<?= e((string)$u['Correo']) ?>" required></label><label>Teléfono<input name="telefono" value="<?= e((string)$u['Telefono']) ?>" required></label></div><div class="form-grid"><label>Ciudad<input name="ciudad" value="<?= e((string)($u['Ciudad']??$u['Direccion']??'')) ?>" required></label><label>Nombre de usuario<input name="usuario" value="<?= e((string)($u['Usuario']??'')) ?>" minlength="3" required></label></div><button class="btn btn-primary full" type="submit">Guardar cambios</button></form></div><?php page_wrap_end();end_app();
